# Curated CogNarr preview site (v1).
#
# This is a STANDALONE, capability-level site. It does NOT load StoryGraph and does
# NOT pull docstrings from the private code, so it can be built and published before
# the code is public. The autogenerated API reference is a later phase (after release).
#
# Build locally (uses the already-instantiated StoryGraph env for Documenter):
#   julia --project=Julia/src/StoryGraph Business/public-release/website/make.jl
# Output: Business/public-release/website/build/index.html  (open in a browser)

using Documenter

makedocs(
    sitename = "CogNarr",
    authors  = "John Boik",
    format   = Documenter.HTML(
        prettyurls = get(ENV, "CI", "false") == "true",  # clean URLs when published; file:// browsing locally
        edit_link  = nothing,            # no "edit on GitHub" link for a draft
        footer     = "CogNarr",
        inventory_version = "0.1.0",
    ),
    pages = [
        "Home"          => "index.md",
        "What it does"  => "capabilities.md",
        "How it works"  => "how-it-works.md",
        "Resources"     => "links.md",
        "Contact"       => "contact.md",
        "About"         => "about.md",
    ],
    remotes  = nothing,
    warnonly = true,                     # a draft should build despite link/doc warnings
)

# deploydocs(...) is intentionally omitted. Deployment happens from the separate
# public site repo (cognarr/cognarr.github.io) via GitHub Actions, after filing.
